import{_ as e,o as d,c,a2 as o}from"./chunks/framework.CdvW4CUT.js";const C=JSON.parse('{"title":"📋 Skylint Rules Catalog (82 Rules)","description":"","frontmatter":{},"headers":[],"relativePath":"rules/index.md","filePath":"rules/index.md"}'),r={name:"rules/index.md"};function n(a,t,l,s,i,_){return d(),c("div",null,[...t[0]||(t[0]=[o('<h1 id="📋-skylint-rules-catalog-82-rules" tabindex="-1">📋 Skylint Rules Catalog (82 Rules) <a class="header-anchor" href="#📋-skylint-rules-catalog-82-rules" aria-label="Permalink to &quot;📋 Skylint Rules Catalog (82 Rules)&quot;">​</a></h1><p>Comprehensive reference for all 82 Clean ABAP, security, performance, and architecture rules in Skylint.</p><h2 id="clean-abap-modern-syntax-29" tabindex="-1">Clean ABAP &amp; Modern Syntax (29) <a class="header-anchor" href="#clean-abap-modern-syntax-29" aria-label="Permalink to &quot;Clean ABAP &amp; Modern Syntax (29)&quot;">​</a></h2><p>Modern language features, expression-oriented coding, and idiomatic Clean ABAP practices.</p><table tabindex="0"><thead><tr><th>Rule ID</th><th>ABAP Class</th><th>Description</th><th style="text-align:center;">Finding Code</th><th style="text-align:center;">Pseudo-Comment</th><th style="text-align:center;">QuickFix</th></tr></thead><tbody><tr><td><a href="/rules/prefer-lines.html"><code>prefer-lines</code></a></td><td><code>ZCL_SKYLINT_PREF_LINES</code></td><td>Prefer lines( ) built-in function over DESCRIBE TABLE ... LINES</td><td style="text-align:center;"><code>DESCRIBELN</code></td><td style="text-align:center;"><code>#EC LINES</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-is-not.html"><code>prefer-is-not</code></a></td><td><code>ZCL_SKYLINT_PREF_IS_NOT</code></td><td>Prefer IS NOT over NOT ... IS</td><td style="text-align:center;"><code>PREFERISNT</code></td><td style="text-align:center;"><code>#EC IS_NOT</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-string-template.html"><code>prefer-string-template</code></a></td><td><code>ZCL_SKYLINT_PREF_STR_TMPL</code></td><td>Prefer string templates over CONCATENATE</td><td style="text-align:center;"><code>CONCATSTR</code></td><td style="text-align:center;"><code>#EC STR_TMPL</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-line-exists.html"><code>prefer-line-exists</code></a></td><td><code>ZCL_SKYLINT_PREF_LINE_EXISTS</code></td><td>Prefer line_exists( ) over READ TABLE ... TRANSPORTING NO FIELDS</td><td style="text-align:center;"><code>PREFLINEX</code></td><td style="text-align:center;"><code>#EC LINE_EXISTS</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-return.html"><code>prefer-return</code></a></td><td><code>ZCL_SKYLINT_PREF_RETURN</code></td><td>Prefer RETURN over EXIT outside loop constructs</td><td style="text-align:center;"><code>EXITOUTLP</code></td><td style="text-align:center;"><code>#EC RETURN</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/merge-nested-ifs.html"><code>merge-nested-ifs</code></a></td><td><code>ZCL_SKYLINT_PREF_MERGE_IFS</code></td><td>Detect consecutive nested IF blocks that can be merged with AND</td><td style="text-align:center;"><code>NESTEDIF</code></td><td style="text-align:center;"><code>#EC MERGE_IFS</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-symbol-operators.html"><code>prefer-symbol-operators</code></a></td><td><code>ZCL_SKYLINT_PREF_SYMBOL_OP</code></td><td>Prefer comparison operators (=, &lt;&gt;, &lt;, &gt;, &lt;=, &gt;=) over legacy textual keywords</td><td style="text-align:center;"><code>PREFEROP</code></td><td style="text-align:center;"><code>#EC SYMBOL_OP</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-new-operator.html"><code>prefer-new-operator</code></a></td><td><code>ZCL_SKYLINT_PREF_NEW_OP</code></td><td>Prefer NEW #( ) constructor expression over legacy CREATE OBJECT</td><td style="text-align:center;"><code>PREFERNEW</code></td><td style="text-align:center;"><code>#EC NEW_OP</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-raise-new.html"><code>prefer-raise-new</code></a></td><td><code>ZCL_SKYLINT_PREF_RAISE_NEW</code></td><td>Prefer RAISE EXCEPTION NEW over RAISE EXCEPTION TYPE</td><td style="text-align:center;"><code>RAISEEXCNE</code></td><td style="text-align:center;"><code>#EC RAISE_NEW</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-xsdbool.html"><code>prefer-xsdbool</code></a></td><td><code>ZCL_SKYLINT_PREF_XSDBOOL</code></td><td>Prefer xsdbool( ) expression over manual IF-ELSE assignment</td><td style="text-align:center;"><code>PREFERXSDB</code></td><td style="text-align:center;"><code>#EC XSDBOOL</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/require-fully-typed.html"><code>require-fully-typed</code></a></td><td><code>ZCL_SKYLINT_PREF_FULL_TYPED</code></td><td>Enforce fully typed constant declarations</td><td style="text-align:center;"><code>FULLYTYPED</code></td><td style="text-align:center;"><code>#EC FULL_TYPED</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-corresponding.html"><code>prefer-corresponding</code></a></td><td><code>ZCL_SKYLINT_PREF_CORRESP</code></td><td>Prefer CORRESPONDING Expression over MOVE-CORRESPONDING</td><td style="text-align:center;"><code>PREFER_COR</code></td><td style="text-align:center;"><code>#EC CORRESP</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-returning.html"><code>prefer-returning</code></a></td><td><code>ZCL_SKYLINT_PREF_RETURNING</code></td><td>Prefer RETURNING over single EXPORTING</td><td style="text-align:center;"><code>PREFER_RET</code></td><td style="text-align:center;"><code>#EC RETURNING</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-class-exceptions.html"><code>prefer-class-exceptions</code></a></td><td><code>ZCL_SKYLINT_PREF_CLASS_EXC</code></td><td>Prefer Class-Based Exceptions over Classic EXCEPTIONS</td><td style="text-align:center;"><code>CLASS_EXC</code></td><td style="text-align:center;"><code>#EC CLASS_EXC</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-final-class.html"><code>prefer-final-class</code></a></td><td><code>ZCL_SKYLINT_PREF_FINAL_CLS</code></td><td>Prefer FINAL Classes by Default</td><td style="text-align:center;"><code>NOT_FINAL</code></td><td style="text-align:center;"><code>#EC FINAL_CLS</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-insert-into.html"><code>prefer-insert-into</code></a></td><td><code>ZCL_SKYLINT_PREF_INSERT</code></td><td>Prefer INSERT ... INTO TABLE over APPEND for table safety</td><td style="text-align:center;"><code>PREF_INSRT</code></td><td style="text-align:center;"><code>#EC INSERT_INTO</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/clean-constructor.html"><code>clean-constructor</code></a></td><td><code>ZCL_SKYLINT_CLEAN_CTOR</code></td><td>Keep constructors clean; avoid heavy business logic/loops/DB access</td><td style="text-align:center;"><code>CTOR_LOGIC</code></td><td style="text-align:center;"><code>#EC CLEAN_CTOR</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-static-classes.html"><code>no-static-classes</code></a></td><td><code>ZCL_SKYLINT_NO_STATIC_CLS</code></td><td>Avoid static-only classes; prefer instantiable interface-based design</td><td style="text-align:center;"><code>STAT_CLASS</code></td><td style="text-align:center;"><code>#EC STATIC_CLS</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-predicate-names.html"><code>prefer-predicate-names</code></a></td><td><code>ZCL_SKYLINT_PREF_PRED_NAME</code></td><td>Enforce predicate naming (IS_, HAS_, CAN_) on boolean methods</td><td style="text-align:center;"><code>BOOL_NAME</code></td><td style="text-align:center;"><code>#EC PRED_NAME</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-nested-try.html"><code>no-nested-try</code></a></td><td><code>ZCL_SKYLINT_NO_NESTED_TRY</code></td><td>Avoid nested TRY blocks; extract inner error handling to helper methods</td><td style="text-align:center;"><code>NESTED_TRY</code></td><td style="text-align:center;"><code>#EC NESTED_TRY</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/test-method-naming.html"><code>test-method-naming</code></a></td><td><code>ZCL_SKYLINT_PREF_TEST_NAME</code></td><td>Enforce test method naming convention (TEST_, SHOULD_) in AUnit</td><td style="text-align:center;"><code>TEST_NAME</code></td><td style="text-align:center;"><code>#EC TEST_NAME</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-final-method.html"><code>prefer-final-method</code></a></td><td><code>ZCL_SKYLINT_PREF_FINAL_METH</code></td><td>Prefer marking non-overridden methods as FINAL</td><td style="text-align:center;"><code>PREF_FINAL</code></td><td style="text-align:center;"><code>#EC FINAL_METHOD</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-string-functions.html"><code>prefer-string-functions</code></a></td><td><code>ZCL_SKYLINT_PREF_STR_FUNC</code></td><td>Detect obsolete string statements; prefer built-in functions</td><td style="text-align:center;"><code>CONDENSE_S</code></td><td style="text-align:center;"><code>#EC STR_FUNC</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-calc-assign-op.html"><code>prefer-calc-assign-op</code></a></td><td><code>ZCL_SKYLINT_PREF_CALC_OP</code></td><td>Prefer calculation assignment operators (+=, -=, *=, /=) over var = var + 1</td><td style="text-align:center;"><code>CALC_ASSGN</code></td><td style="text-align:center;"><code>#EC CALC_ASSIGN</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-early-continue.html"><code>prefer-early-continue</code></a></td><td><code>ZCL_SKYLINT_PREF_EARLY_CONT</code></td><td>Use early CONTINUE guard clause instead of wrapping loop in IF block</td><td style="text-align:center;"><code>GUARD_LOOP</code></td><td style="text-align:center;"><code>#EC EARLY_CONTINUE</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/prefer-early-return.html"><code>prefer-early-return</code></a></td><td><code>ZCL_SKYLINT_PREF_EARLY_RET</code></td><td>Use early RETURN guard clause instead of wrapping method in IF block</td><td style="text-align:center;"><code>GUARD_METH</code></td><td style="text-align:center;"><code>#EC EARLY_RETURN</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/require-decl-order.html"><code>require-decl-order</code></a></td><td><code>ZCL_SKYLINT_PREF_DECL_ORDER</code></td><td>Enforce local declaration order (TYPES -&gt; CONSTANTS -&gt; DATA -&gt; FIELD-SYMBOLS)</td><td style="text-align:center;"><code>DECL_ORDER</code></td><td style="text-align:center;"><code>#EC DECL_ORDER</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-param-escape.html"><code>no-param-escape</code></a></td><td><code>ZCL_SKYLINT_NO_PARAM_ESCAPE</code></td><td>Detect unnecessary exclamation mark parameter escape (!iv_param)</td><td style="text-align:center;"><code>PARAM_ESCP</code></td><td style="text-align:center;"><code>#EC PARAM_ESCAPE</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/prefer-case.html"><code>prefer-case</code></a></td><td><code>ZCL_SKYLINT_PREF_CASE</code></td><td>Change IF to CASE when checking the same variable against multiple values</td><td style="text-align:center;"><code>USE_CASE</code></td><td style="text-align:center;"><code>#EC PREF_CASE</code></td><td style="text-align:center;">—</td></tr></tbody></table><h2 id="anti-patterns-bad-practices-32" tabindex="-1">Anti-Patterns &amp; Bad Practices (32) <a class="header-anchor" href="#anti-patterns-bad-practices-32" aria-label="Permalink to &quot;Anti-Patterns &amp; Bad Practices (32)&quot;">​</a></h2><p>Discouraged language constructs, legacy statements, and redundant syntax.</p><table tabindex="0"><thead><tr><th>Rule ID</th><th>ABAP Class</th><th>Description</th><th style="text-align:center;">Finding Code</th><th style="text-align:center;">Pseudo-Comment</th><th style="text-align:center;">QuickFix</th></tr></thead><tbody><tr><td><a href="/rules/no-call-method.html"><code>no-call-method</code></a></td><td><code>ZCL_SKYLINT_NO_CALL_METHOD</code></td><td>Avoid static CALL METHOD statements</td><td style="text-align:center;"><code>CALLMETHOD</code></td><td style="text-align:center;"><code>#EC CALL_METH</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-default-key.html"><code>no-default-key</code></a></td><td><code>ZCL_SKYLINT_NO_DEFAULT_KEY</code></td><td>Avoid WITH DEFAULT KEY; prefer EMPTY KEY or explicit keys</td><td style="text-align:center;"><code>DEFAULTKEY</code></td><td style="text-align:center;"><code>#EC DEFAULT_KEY</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-me-reference.html"><code>no-me-reference</code></a></td><td><code>ZCL_SKYLINT_NO_ME_REFERENCE</code></td><td>Avoid self-reference ME-&gt;</td><td style="text-align:center;"><code>AVOIDME</code></td><td style="text-align:center;"><code>#EC ME</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-exporting.html"><code>no-exporting</code></a></td><td><code>ZCL_SKYLINT_NO_EXPORTING</code></td><td>Omit explicit EXPORTING in method calls</td><td style="text-align:center;"><code>OMITEXPORT</code></td><td style="text-align:center;"><code>#EC EXPORTING</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-chained-assignment.html"><code>no-chained-assignment</code></a></td><td><code>ZCL_SKYLINT_NO_CHAIN_ASSIGN</code></td><td>Avoid assignment chaining (a = b = c)</td><td style="text-align:center;"><code>ASSIGNCHN</code></td><td style="text-align:center;"><code>#EC CHAIN_ASSIGN</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-chained-decl.html"><code>no-chained-decl</code></a></td><td><code>ZCL_SKYLINT_NO_CHAIN_DECL</code></td><td>Avoid chained declarations (DATA:, TYPES:, etc.)</td><td style="text-align:center;"><code>CHAINDECL</code></td><td style="text-align:center;"><code>#EC CHAIN_DECL</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-boolean-comparison.html"><code>no-boolean-comparison</code></a></td><td><code>ZCL_SKYLINT_NO_BOOL_COMPARE</code></td><td>Avoid comparing boolean method calls to boolean literals</td><td style="text-align:center;"><code>BOOLCOMP</code></td><td style="text-align:center;"><code>#EC BOOL_COMPARE</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-check-in-loop.html"><code>no-check-in-loop</code></a></td><td><code>ZCL_SKYLINT_NO_CHECK_IN_LOOP</code></td><td>Avoid CHECK in loop/iteration structures (prefer IF ... CONTINUE)</td><td style="text-align:center;"><code>CHKINLOOP</code></td><td style="text-align:center;"><code>#EC CHECK_IN_LOOP</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-empty-block.html"><code>no-empty-block</code></a></td><td><code>ZCL_SKYLINT_NO_EMPTY_BLOCK</code></td><td>Detect empty control blocks (IF, CASE, LOOP, TRY, etc.)</td><td style="text-align:center;"><code>EMPTYCTRL</code></td><td style="text-align:center;"><code>#EC EMPTY_BLOCK</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-empty-catch.html"><code>no-empty-catch</code></a></td><td><code>ZCL_SKYLINT_NO_EMPTY_CATCH</code></td><td>Detect empty CATCH blocks swallowing exceptions</td><td style="text-align:center;"><code>EMPTYCATCH</code></td><td style="text-align:center;"><code>#EC NO_HANDLER</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-duplicate-conditions.html"><code>no-duplicate-conditions</code></a></td><td><code>ZCL_SKYLINT_NO_DUP_COND</code></td><td>Detect identical branch conditions in IF/ELSEIF and CASE/WHEN</td><td style="text-align:center;"><code>DUPCOND</code></td><td style="text-align:center;"><code>#EC DUP_COND</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-unreachable-code.html"><code>no-unreachable-code</code></a></td><td><code>ZCL_SKYLINT_NO_UNREACHABLE</code></td><td>Detect unreachable code following unconditional jump statements</td><td style="text-align:center;"><code>UNREACHCD</code></td><td style="text-align:center;"><code>#EC UNREACHABLE</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-single-when.html"><code>no-single-when</code></a></td><td><code>ZCL_SKYLINT_NO_SINGLE_WHEN</code></td><td>Avoid short CASE constructs with only one WHEN branch; prefer IF</td><td style="text-align:center;"><code>SHORTCASE</code></td><td style="text-align:center;"><code>#EC SINGLE_WHEN</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-yoda-conditions.html"><code>no-yoda-conditions</code></a></td><td><code>ZCL_SKYLINT_NO_YODA_COND</code></td><td>Avoid Yoda conditions in comparison expressions</td><td style="text-align:center;"><code>YODACOND</code></td><td style="text-align:center;"><code>#EC YODA_COND</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-receiving.html"><code>no-receiving</code></a></td><td><code>ZCL_SKYLINT_NO_RECEIVING</code></td><td>Omit RECEIVING in method calls</td><td style="text-align:center;"><code>OMITRECEIV</code></td><td style="text-align:center;"><code>#EC RECEIVING</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-static-via-instance.html"><code>no-static-via-instance</code></a></td><td><code>ZCL_SKYLINT_NO_STATIC_ARROW</code></td><td>Avoid calling static methods via instance arrow (-&gt;)</td><td style="text-align:center;"><code>STATICVIAI</code></td><td style="text-align:center;"><code>#EC STATIC_ARROW</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-public-attributes.html"><code>no-public-attributes</code></a></td><td><code>ZCL_SKYLINT_NO_PUBLIC_ATTR</code></td><td>Avoid mutable public attributes in classes</td><td style="text-align:center;"><code>NOPUBATTR</code></td><td style="text-align:center;"><code>#EC PUBLIC_ATTR</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-obsolete-statements.html"><code>no-obsolete-statements</code></a></td><td><code>ZCL_SKYLINT_NO_OBSOLETE</code></td><td>Avoid obsolete statements (MOVE, REFRESH, etc.)</td><td style="text-align:center;"><code>OBSOLETE</code></td><td style="text-align:center;"><code>#EC OBSOLETE</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-scope-leak.html"><code>no-scope-leak</code></a></td><td><code>ZCL_SKYLINT_NO_SCOPE_LEAK</code></td><td>Scope of variable (avoid variable leaking outside control blocks)</td><td style="text-align:center;"><code>SCOPELEAK</code></td><td style="text-align:center;"><code>#EC SCOPE_LEAK</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-self-assignment.html"><code>no-self-assignment</code></a></td><td><code>ZCL_SKYLINT_NO_SELF_ASSIGN</code></td><td>Detect Identical Self Assignments</td><td style="text-align:center;"><code>IDENTMOVE</code></td><td style="text-align:center;"><code>#EC SELF_ASSIGN</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-single-param-name.html"><code>no-single-param-name</code></a></td><td><code>ZCL_SKYLINT_NO_PARAM_NAME</code></td><td>Omit parameter name in single parameter method call</td><td style="text-align:center;"><code>OMITPARM</code></td><td style="text-align:center;"><code>#EC PARAM_NAME</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-try-without-catch.html"><code>no-try-without-catch</code></a></td><td><code>ZCL_SKYLINT_NO_TRY_NO_CATCH</code></td><td>Detect TRY without CATCH</td><td style="text-align:center;"><code>TRYWITHOUT</code></td><td style="text-align:center;"><code>#EC TRY_NO_CATCH</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-sy-modify.html"><code>no-sy-modify</code></a></td><td><code>ZCL_SKYLINT_NO_SY_MODIFY</code></td><td>Avoid sy-* System Variable Modification</td><td style="text-align:center;"><code>SYS_VAR_MD</code></td><td style="text-align:center;"><code>#EC SY_MODIFY</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-raise-shortdump.html"><code>no-raise-shortdump</code></a></td><td><code>ZCL_SKYLINT_NO_SHORTDUMP</code></td><td>Avoid RAISE SHORTDUMP (prefer graceful exceptions)</td><td style="text-align:center;"><code>SHORTDUMP</code></td><td style="text-align:center;"><code>#EC SHORTDUMP</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-magic-numbers.html"><code>no-magic-numbers</code></a></td><td><code>ZCL_SKYLINT_NO_MAGIC_NUMBERS</code></td><td>Avoid magic numbers in code; use named constants</td><td style="text-align:center;"><code>MAGIC_NUM</code></td><td style="text-align:center;"><code>#EC MAGIC_NUMBERS</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-obsolete-loop-control.html"><code>no-obsolete-loop-control</code></a></td><td><code>ZCL_SKYLINT_NO_OBS_LOOP_CTL</code></td><td>Avoid obsolete control statements (ON CHANGE OF, AT NEW, SUM) in LOOP</td><td style="text-align:center;"><code>OBS_L_CTRL</code></td><td style="text-align:center;"><code>#EC OBS_LOOP_CTL</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-like-objects.html"><code>no-like-objects</code></a></td><td><code>ZCL_SKYLINT_NO_LIKE_OBJECTS</code></td><td>Avoid LIKE referencing data objects; use explicit TYPE</td><td style="text-align:center;"><code>AVOID_LIKE</code></td><td style="text-align:center;"><code>#EC LIKE_OBJECTS</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-interface-data.html"><code>no-interface-data</code></a></td><td><code>ZCL_SKYLINT_NO_INTF_DATA</code></td><td>Avoid mutable DATA declarations in interfaces; allow only CONSTANTS</td><td style="text-align:center;"><code>INTF_DATA</code></td><td style="text-align:center;"><code>#EC INTF_DATA</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-message-raising.html"><code>no-message-raising</code></a></td><td><code>ZCL_SKYLINT_NO_MSG_RAISING</code></td><td>Avoid obsolete MESSAGE ... RAISING; use class-based exceptions</td><td style="text-align:center;"><code>MSG_RAISE</code></td><td style="text-align:center;"><code>#EC MSG_RAISING</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-form-routines.html"><code>no-form-routines</code></a></td><td><code>ZCL_SKYLINT_NO_FORM</code></td><td>Avoid obsolete FORM routines; use modern methods in ABAP Cloud</td><td style="text-align:center;"><code>AVOID_FORM</code></td><td style="text-align:center;"><code>#EC NO_FORM</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-unused-variables.html"><code>no-unused-variables</code></a></td><td><code>ZCL_SKYLINT_NO_UNUSED_VARS</code></td><td>Detect unused local variables and field symbols</td><td style="text-align:center;"><code>UNUSED_VAR</code></td><td style="text-align:center;"><code>#EC NEEDED</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-inline-length.html"><code>no-inline-length</code></a></td><td><code>ZCL_SKYLINT_NO_INLINE_LEN</code></td><td>Avoid inline length specification in declarations</td><td style="text-align:center;"><code>PAREN_LEN</code></td><td style="text-align:center;"><code>#EC PAREN_LEN</code></td><td style="text-align:center;">⚡ Ready</td></tr></tbody></table><h2 id="performance-database-5" tabindex="-1">Performance &amp; Database (5) <a class="header-anchor" href="#performance-database-5" aria-label="Permalink to &quot;Performance &amp; Database (5)&quot;">​</a></h2><p>Database query efficiency, buffer protection, and internal table operation guidelines.</p><table tabindex="0"><thead><tr><th>Rule ID</th><th>ABAP Class</th><th>Description</th><th style="text-align:center;">Finding Code</th><th style="text-align:center;">Pseudo-Comment</th><th style="text-align:center;">QuickFix</th></tr></thead><tbody><tr><td><a href="/rules/no-db-in-loop.html"><code>no-db-in-loop</code></a></td><td><code>ZCL_SKYLINT_NO_DB_IN_LOOP</code></td><td>Avoid database access inside loop iterations</td><td style="text-align:center;"><code>DBINLOOP</code></td><td style="text-align:center;"><code>#EC DB_IN_LOOP</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-empty-fae.html"><code>no-empty-fae</code></a></td><td><code>ZCL_SKYLINT_NO_EMPTY_FAE</code></td><td>Unsecure FOR ALL ENTRIES (Missing empty itab check)</td><td style="text-align:center;"><code>FAENOCHECK</code></td><td style="text-align:center;"><code>#EC EMPTY_FAE</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-select-star.html"><code>no-select-star</code></a></td><td><code>ZCL_SKYLINT_NO_SELECT_STAR</code></td><td>Select performance (Avoid SELECT * and SELECT ... ENDSELECT)</td><td style="text-align:center;"><code>SELECTSTAR</code></td><td style="text-align:center;"><code>#EC SELECT_STAR</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/require-order-by.html"><code>require-order-by</code></a></td><td><code>ZCL_SKYLINT_PREF_ORDER_BY</code></td><td>SELECT UP TO 1 ROWS requires ORDER BY</td><td style="text-align:center;"><code>SELECT_UP</code></td><td style="text-align:center;"><code>#EC ORDER_BY</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/require-transporting.html"><code>require-transporting</code></a></td><td><code>ZCL_SKYLINT_PREF_TRANSPORT</code></td><td>Avoid full-line MODIFY itab inside LOOP without TRANSPORTING clause</td><td style="text-align:center;"><code>FULL_MODIF</code></td><td style="text-align:center;"><code>#EC TRANSPORTING</code></td><td style="text-align:center;">—</td></tr></tbody></table><h2 id="security-robustness-10" tabindex="-1">Security &amp; Robustness (10) <a class="header-anchor" href="#security-robustness-10" aria-label="Permalink to &quot;Security &amp; Robustness (10)&quot;">​</a></h2><p>Authorizations, dynamic execution sanitation, error handling, and runtime safety.</p><table tabindex="0"><thead><tr><th>Rule ID</th><th>ABAP Class</th><th>Description</th><th style="text-align:center;">Finding Code</th><th style="text-align:center;">Pseudo-Comment</th><th style="text-align:center;">QuickFix</th></tr></thead><tbody><tr><td><a href="/rules/no-dangerous-dynamic.html"><code>no-dangerous-dynamic</code></a></td><td><code>ZCL_SKYLINT_NO_DYNAMIC_STMT</code></td><td>Dangerous / Unmanaged Dynamic Statements</td><td style="text-align:center;"><code>DANGER_STM</code></td><td style="text-align:center;"><code>#EC DYNAMIC_STMT</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/require-auth-check.html"><code>require-auth-check</code></a></td><td><code>ZCL_SKYLINT_PREF_AUTH_CHECK</code></td><td>Call Transaction Authority Check</td><td style="text-align:center;"><code>AUTH_CHECK</code></td><td style="text-align:center;"><code>#EC AUTH_CHECK</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-catch-cx-root.html"><code>no-catch-cx-root</code></a></td><td><code>ZCL_SKYLINT_NO_CATCH_ROOT</code></td><td>Avoid generic CATCH cx_root; catch specific exception classes</td><td style="text-align:center;"><code>CATCH_ROOT</code></td><td style="text-align:center;"><code>#EC CATCH_ROOT</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-raise-cx-sy.html"><code>no-raise-cx-sy</code></a></td><td><code>ZCL_SKYLINT_NO_RAISE_CX_SY</code></td><td>Avoid raising SAP internal system exceptions (cx_sy_*)</td><td style="text-align:center;"><code>RAISE_SYS</code></td><td style="text-align:center;"><code>#EC RAISE_CX_SY</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/require-subrc-check.html"><code>require-subrc-check</code></a></td><td><code>ZCL_SKYLINT_CHECK_SUBRC</code></td><td>Check sy-subrc after DB, table and string operations</td><td style="text-align:center;"><code>CHECKSUBRC</code></td><td style="text-align:center;"><code>#EC CHECK_SUBRC</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-client-specified.html"><code>no-client-specified</code></a></td><td><code>ZCL_SKYLINT_NO_CLIENT_SPEC</code></td><td>Avoid USING CLIENT or CLIENT SPECIFIED in ABAP SQL</td><td style="text-align:center;"><code>CLIENT_SPE</code></td><td style="text-align:center;"><code>#EC CLIENT_SPEC</code></td><td style="text-align:center;">⚡ Ready</td></tr><tr><td><a href="/rules/no-commit-work.html"><code>no-commit-work</code></a></td><td><code>ZCL_SKYLINT_NO_COMMIT_WORK</code></td><td>Avoid COMMIT WORK / ROLLBACK WORK in behavior implementations</td><td style="text-align:center;"><code>NO_COMMIT</code></td><td style="text-align:center;"><code>#EC COMMIT_WORK</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-raw-dynamic-sql.html"><code>no-raw-dynamic-sql</code></a></td><td><code>ZCL_SKYLINT_NO_RAW_DYN_SQL</code></td><td>Avoid dynamic SQL table or clause names without sanitization</td><td style="text-align:center;"><code>DYN_SQL</code></td><td style="text-align:center;"><code>#EC RAW_DYN_SQL</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-production-assert.html"><code>no-production-assert</code></a></td><td><code>ZCL_SKYLINT_NO_PROD_ASSERT</code></td><td>Detect native ASSERT in production code; use exceptions instead</td><td style="text-align:center;"><code>PROD_ASSRT</code></td><td style="text-align:center;"><code>#EC PROD_ASSERT</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/no-forbidden-statements.html"><code>no-forbidden-statements</code></a></td><td><code>ZCL_SKYLINT_NO_FORBIDDEN</code></td><td>Avoid use of certain statements (BREAK, STATICS, DEFINE, EXPORT)</td><td style="text-align:center;"><code>AVOID_USE</code></td><td style="text-align:center;"><code>#EC FORBIDDEN</code></td><td style="text-align:center;">—</td></tr></tbody></table><h2 id="metrics-complexity-limits-6" tabindex="-1">Metrics &amp; Complexity Limits (6) <a class="header-anchor" href="#metrics-complexity-limits-6" aria-label="Permalink to &quot;Metrics &amp; Complexity Limits (6)&quot;">​</a></h2><p>Quantitative boundaries for method size, nesting depth, parameter counts, and cyclomatic complexity.</p><table tabindex="0"><thead><tr><th>Rule ID</th><th>ABAP Class</th><th>Description</th><th style="text-align:center;">Finding Code</th><th style="text-align:center;">Pseudo-Comment</th><th style="text-align:center;">QuickFix</th></tr></thead><tbody><tr><td><a href="/rules/max-params.html"><code>max-params</code></a></td><td><code>ZCL_SKYLINT_MAX_PARAMS</code></td><td>Method signature cleanliness (excessive parameter count)</td><td style="text-align:center;"><code>PARAMCOUNT</code></td><td style="text-align:center;"><code>#EC MAX_PARAMS</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/max-method-length.html"><code>max-method-length</code></a></td><td><code>ZCL_SKYLINT_MAX_METHOD_LEN</code></td><td>Method Length Limit (excessive statement count)</td><td style="text-align:center;"><code>METHOD_LEN</code></td><td style="text-align:center;"><code>#EC METHOD_LEN</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/max-nesting-depth.html"><code>max-nesting-depth</code></a></td><td><code>ZCL_SKYLINT_MAX_NESTING</code></td><td>Nesting Depth Limit (excessive control block nesting)</td><td style="text-align:center;"><code>NESTING_DP</code></td><td style="text-align:center;"><code>#EC NESTING</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/max-cyclomatic-complexity.html"><code>max-cyclomatic-complexity</code></a></td><td><code>ZCL_SKYLINT_MAX_CYCLO_COMP</code></td><td>Cyclomatic Complexity Threshold</td><td style="text-align:center;"><code>CYCLO_COMP</code></td><td style="text-align:center;"><code>#EC CYCLO_COMP</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/max-inheritance-depth.html"><code>max-inheritance-depth</code></a></td><td><code>ZCL_SKYLINT_MAX_INHERIT</code></td><td>Avoid deep class inheritance hierarchies</td><td style="text-align:center;"><code>DEEP_INHRT</code></td><td style="text-align:center;"><code>#EC INHERIT_DEPTH</code></td><td style="text-align:center;">—</td></tr><tr><td><a href="/rules/max-attributes.html"><code>max-attributes</code></a></td><td><code>ZCL_SKYLINT_MAX_ATTRIBUTES</code></td><td>Limit number of member attributes in a class (God Class smell)</td><td style="text-align:center;"><code>ATTR_COUNT</code></td><td style="text-align:center;"><code>#EC ATTRIBUTES</code></td><td style="text-align:center;">—</td></tr></tbody></table>',17)])])}const y=e(r,[["render",n]]);export{C as __pageData,y as default};
